const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const deathValley = ee.Geometry.Point([-116.8167, 36.5054]); // Death Valley coordinates
  const globalRegion = ee.Geometry.Polygon([
    [[-180, -60], [180, -60], [180, 75], [-180, 75], [-180, -60]]
  ], null, false);

  const startDate = '2004-01-01';
  const endDate = '2004-12-31';

  // 2. Data Acquisition
  let collection = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterDate(startDate, endDate)
    .select('LST_Day_1km');

  // Check if collection has data
  const colSize = await collection.size().getInfo();
  console.log(`Total MODIS images in 2004: ${colSize}`);

  if (colSize === 0) {
    // Try alternate version
    collection = ee.ImageCollection('MODIS/006/MOD11A1')
      .filterDate(startDate, endDate)
      .select('LST_Day_1km');

    const altSize = await collection.size().getInfo();
    console.log(`Alternate collection size: ${altSize}`);

    if (altSize === 0) {
      console.log("No MODIS LST data found for 2004.");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 3. Processing - Convert to Celsius and get maximum
  const lstCelsius = collection.map(function(img) {
    return img.multiply(0.02).subtract(273.15).copyProperties(img, ['system:time_start']);
  });

  // Get maximum LST image (pixel-wise max across all dates)
  const maxLST = lstCelsius.max();

  // 4. Calculate Death Valley maximum
  const dvStats = await maxLST.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: deathValley.buffer(5000), // 5km buffer
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const dvMax = dvStats.LST_Day_1km;

  // Count valid pixels in Death Valley
  const dvCount = await maxLST.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: deathValley.buffer(5000),
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  console.log(`Death Valley max LST: ${dvMax !== null ? dvMax.toFixed(2) + '°C' : 'null'}`);
  console.log(`Death Valley valid pixels: ${dvCount.LST_Day_1km || 0}`);

  if (dvCount.LST_Day_1km === 0) {
    console.log("No valid pixels in Death Valley.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Calculate global maximum (sample to avoid timeout)
  const globalStats = await maxLST.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: globalRegion,
    scale: 5000,
    maxPixels: 1e9,
    bestEffort: true
  }).getInfo();

  const globalMax = globalStats.LST_Day_1km;

  console.log(`Global max LST: ${globalMax !== null ? globalMax.toFixed(2) + '°C' : 'null'}`);

  // 6. Validation & Final Answer
  if (dvMax === null || globalMax === null || dvMax < -50 || dvMax > 100 || globalMax < -50 || globalMax > 100) {
    console.log("Invalid temperature values detected.");
    console.log("<answer>C3</answer>");
    return;
  }

  const tolerance = 0.5; // 0.5°C tolerance
  if (dvMax >= globalMax - tolerance) {
    console.log(`Death Valley recorded the highest max LST in 2004 (DV: ${dvMax.toFixed(2)}°C >= Global: ${globalMax.toFixed(2)}°C)`);
    console.log("<answer>A</answer>");
  } else {
    console.log(`Death Valley did NOT record the highest max LST in 2004 (DV: ${dvMax.toFixed(2)}°C < Global: ${globalMax.toFixed(2)}°C)`);
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
